(580308, 'zhCN', '升天之路·通配：卷轴回购', '可以购买此前已获得但尚未使用的命运卷轴。每次威望转生时都会开放此选项。', '- 达到满级后，拜访塞拉斯·暗月买回任何未使用的命运卷轴。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580309, 'zhCN', '升天之路·通配：威望转生', '威望转生会重置角色等级，但保留已有进度。每次威望转生都能解锁强力奖励并尝试全新流派。', '- 与克罗米交谈，让你的角色威望转生并重置为 1 级。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580310, 'zhCN', '升天之路·通配：快速重掷', '使用快速重掷快速翻阅命运卷轴，找出最契合你流派的法术与天赋。', '- 满级后打开角色提升界面，启用快速重掷模式。', '', '返回召集板。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(580311, 'zhCN', '升天之路·通配：快速重掷完整流派', '使用英雄建筑师将推荐流派导入快速重掷模式。推荐流派针对快速成长进行了优化。', '- 打开英雄建筑师，选择一套推荐流派用于快速重掷。', '', '返回召集板。', NULL);
